 54	      handleRequest(req, res, ledgerRoot, configPath, 0, logsDir).catch((err) => {
 55	        process.stderr.write(`[test-server] Unhandled: ${String(err)}\n`);
 56	        if (!res.headersSent) {
 57	          res.writeHead(500, { 'Content-Type': 'application/json' });
 58	          res.end(JSON.stringify({ error: { code: 'INTERNAL_ERROR', message: 'error' } }));
 59	        }
 60	      });
 61	    });
 62	
 63	    server.listen(0, '127.0.0.1', () => {
 64	      const addr = server.address();
 65	      if (addr && typeof addr === 'object') {
 66	        resolve({ server, baseUrl: `http://127.0.0.1:${addr.port}`, port: addr.port });
 67	      } else {
 68	        reject(new Error('Could not determine server port'));
 69	      }
 70	    });
 71	
 72	    server.on('error', reject);
 73	  });
 74	}
